-- 자녀를 위한 365일 축복 기도문 — 1/6 · 1/13 · 12/15 셋째 문단 끝 문장 보충 (3편 덮어쓰기)
-- 2026-11-17 · 1/20 · 1/27 같은 문단 기준 · 여러 번 실행해도 안전합니다.
SET XACT_ABORT ON;
BEGIN TRAN;

MERGE dbo.Prayer365 AS t
USING (VALUES
('0106', N'하나님을 찾는 마음을 지니도록 하옵소서', N'히 11:6',
 N'믿음이 없이는 기쁘시게 못하나니 하나님께 나아가는 자는 반드시 그가 계신 것과 또한 그가 자기를 찾는 자들에게 상 주시는 이심을 믿어야 할찌니라',
 N'전능하신 하나님,
우주만물을 지으시고 심히 좋아하셨던 하나님을 찬양합니다. 지으신 것들을 보시면서 만족해 하셨던 그 마음을 저의 아이에게 주시기 원합니다. 하나님이 창조적인 존재로 자신을 바라보게 하시고, 자아에 대한 긍정의 마음을 갖게 하옵소서. 늘 자신을 향해서 격려하게 하시고, 자기를 존중하게 하옵소서.
은혜를 베푸시는 하나님,
저의 아이가 한 해의 삶을 살아가면서 입술에 은혜가 있기를 원합니다. 그러므로 이미 주 안에서 모든 것을 할 수 있다고 선언하신 말씀에 순종하게 하옵소서. 그가 그리스도 안에서 모든 것을 할 수 있게 하셨으니 그 은혜에 감사하면서 담대한 말을 하도록 하옵소서. 하나님의 도우심으로 할 수 있다는 용기를 지니게 하시고, 자신에 대한 소망을 갖게 하옵소서.
예배를 받으시는 하나님,
저의 아이가 주 여호와의 이름을 높여드리며 예배드리는 시간을 사모하기를 소망합니다. 주님의 날이 세상으로부터 구별되고, 하나님께 영광을 드리기를 바라는 마음을 주옵소서. 하늘의 하나님께는 영화로움을 드리고 주님께서 세상을 향해서 복을 주시는 예배를 기다리게 하옵소서. 이를 위해서 오늘 밤은 거룩히 보내게 하시기를 원하면서 예수님의 이름으로 기도드립니다. 아멘.',
 N'[{"From":"(8 11:0)","To":"히 11:6"},{"From":"못하나너","To":"못하나니"},{"From":"자들에체","To":"자들에게"},{"From":"전능하신 하나님","To":"전능하신 하나님,"},{"From":"원합니 다","To":"원합니다"},{"From":"긍 정의","To":"긍정의"},{"From":"은혜를 베푸시는 하나님","To":"은혜를 베푸시는 하나님,"},{"From":"하셨으 니","To":"하셨으니"},{"From":"하읍소서","To":"하옵소서"},{"From":"도우 심으로","To":"도우심으로"},{"From":"하 옵소서","To":"하옵소서"},{"From":"높어드리며","To":"높여드리며"},{"From":"사모 하기를","To":"사모하기를"},{"From":"영광 을드리기를","To":"영광을 드리기를"},{"From":"주옵소서,","To":"주옵소서."},{"From":"드 리고","To":"드리고"},{"From":"거룩 히","To":"거룩히"},{"From":"아멘","To":"아멘."},{"From":"21","To":"(쪽 번호 — 뺌)"},{"From":"복을 주시는 이를 위해서","To":"복을 주시는 예배를 기다리게 하옵소서. 이를 위해서 (빠진 문장 — 1/20·1/27 같은 문단 기준 보충)"}]'),
('0113', N'오직 하나님을 의지하게 하옵소서', N'잠 14:26',
 N'여호와를 경외하는 자에게는 견고한 의뢰가 있나니 그 자녀들에게 피난처가 있으리라',
 N'찬양받으실 하나님,
주일 아침에, 저의 아이를 위해 축복하며 간구합니다. 거룩한 날에 신령과 진정으로 예배하려는 마음을 갖게 하옵소서. 오늘, 교회에서 많은 친구들을 만나고 함께 찬양을 할 때, 여호와 하나님께만 영광을 드리게 하옵소서. 좋은 교회를 허락하시고, 믿음의 친구들을 사귀게 하시니 참으로 감사드립니다.
교회로 모이게 하시는 하나님,
저의 아이에게 주님의 사랑을 입은 친구들을 붙여 주옵소서. 지혜로운 친구들을 붙여주시기를 간절히 바랍니다. 하나님을 경외하는 아이들을 친구로 사귀도록 이끌어 주옵소서. 하나님을 두려워할 줄 아는 친구들과 함께 하게 하옵소서. 주님께 영광을 드리려고 마음을 다하는 친구들과 함께 하게 하옵소서. 함께 기도하고, 주님의 은혜를 나누는 친구들이 되기를 소망합니다.
예배를 받으시는 하나님,
저의 아이가 주 여호와의 이름을 높여드리며 예배드리는 시간을 사모하기를 소망합니다. 주님의 날이 세상으로부터 구별되고, 하나님께 영광을 드리는 시간이기를 바라는 마음을 주옵소서. 하늘의 하나님께는 영화로움을 드리고 주님께서 세상을 향해서 복을 주시는 예배를 기다리게 하옵소서. 이를 위해서 오늘 밤은 거룩히 보내게 해 주시기를 원하면서 예수님의 이름으로 기도드립니다. 아멘.',
 N'[{"From":"잠 14:20","To":"잠 14:26"},{"From":"의픽가 있나너","To":"의뢰가 있나니"},{"From":"자녀들에비","To":"자녀들에게"},{"From":"신 령과","To":"신령과"},{"From":"참 으로감사드립니다","To":"참으로 감사드립니다"},{"From":"주읍소서","To":"주옵소서"},{"From":"하움소서","To":"하옵소서"},{"From":"되 기를","To":"되기를"},{"From":"사모 하기를","To":"사모하기를"},{"From":"영광 을드리는","To":"영광을 드리는"},{"From":"영화 로움을","To":"영화로움을"},{"From":"하 옵소서","To":"하옵소서"},{"From":"28 자녀를 위한 365일축복 기도문","To":"(쪽 머리글 — 뺌)"},{"From":"보내게 하옵소서. (끝)","To":"보내게 해 주시기를 원하면서 예수님의 이름으로 기도드립니다. 아멘. (빠진 끝 문장 — 1/20·1/27 같은 문단 기준 보충)"}]'),
('1215', N'어려운 애들과 함께 하게 하옵소서', N'사 40:3-4',
 N'외치는 자의 소리여 가로되 너희는 광야에서 여호와의 길을 예비하라 사막에서 우리 하나님의 대로를 평탄케 하라 골짜기마다 돋우어지며 산마다, 작은 산마다 낮아지며 고르지 않은 곳이 평탄케 되며 험한 곳이 평지가 될 것이요',
 N'영광의 하나님,
성탄절이 우리를 위해 예수님이 오셨음을 축하하는 시간이라면, 저의 아이가 예수님의 사랑을 이웃에게 나누어 주도록 이끌어 주옵소서. 그가 주님으로부터 받은 것은 참으로 많습니다. 우선, 그의 마음에 가득 차 있는 하나님의 사랑을 나누게 해 주시기를 소망합니다.
하나님이 우리에게 오심처럼, 저의 아이도 남들에게 다가가기 원합니다. 자기가 갖고 있지만, 남들에게 없는 것을 보게 하옵소서. 사실, 제 것이 제 것이 아니고 거저 받은 것들인데, 없어서 힘들어 하는 이들에게 나누어 주도록 하옵소서.
아주 적은 것이지만 자신의 물건을 이웃과 나눌 수 있게 하시고, 군것질을 할 때, 어려운 애들과 함께 할 수 있도록 해 주옵소서. 그의 마음에 긍휼이 있게 하옵소서. 사랑이 있는 곳에 하나님이 계심을 믿습니다.
예배를 받으시는 하나님,
저의 아이가 주 여호와의 이름을 높여드리며 예배드리는 시간을 사모하기를 소망합니다. 주님의 날이 세상으로부터 구별되고, 하나님께 영광을 드리는 시간이기를 바라는 마음을 주옵소서. 하늘의 하나님께는 영화로움을 드리고 주님께서 세상을 향해서 복을 주시는 예배를 기다리게 하옵소서. 이를 위해서 오늘 밤은 거룩히 보내게 해 주시기를 원하면서 예수님의 이름으로 기도드립니다. 아멘.',
 N'[{"From":"어려운 애플과","To":"어려운 애들과"},{"From":"길윤","To":"길을"},{"From":"하 나님","To":"하나님"},{"From":"우어지며","To":"돋우어지며"},{"From":"고르 지","To":"고르지"},{"From":"평단케","To":"평탄케"},{"From":"평지가 됩 것이요","To":"평지가 될 것이요"},{"From":"차 있 는","To":"차 있는"},{"From":"소망합니다 하나님이","To":"소망합니다. / 하나님이"},{"From":"원합니 다","To":"원합니다"},{"From":"제 것 이","To":"제 것이"},{"From":"나 누어","To":"나누어"},{"From":"하읍소서","To":"하옵소서"},{"From":"군것 질","To":"군것질"},{"From":"사모 하기를","To":"사모하기를"},{"From":"영광 을","To":"영광을"},{"From":"영화 로움을","To":"영화로움을"},{"From":"에배를","To":"예배를"},{"From":"하 옵소서","To":"하옵소서"},{"From":"364 자녀를 위한 365일 축복 기도문","To":"(쪽 머리글 — 뺌)"},{"From":"보내게 하옵소서. / 원하면서","To":"보내게 해 주시기를 원하면서 (1/20·1/27 같은 문단 기준)"}]')
) AS s (MonthDay, Title, VerseRef, VerseText, Body, Fixes)
ON t.MonthDay = s.MonthDay
WHEN MATCHED THEN UPDATE SET Title = s.Title, VerseRef = s.VerseRef, VerseText = s.VerseText, Body = s.Body, Fixes = s.Fixes,
     IsReviewed = 1, UpdatedAt = DATEADD(HOUR, 9, SYSUTCDATETIME()), UpdatedBy = N'Claude'
WHEN NOT MATCHED THEN INSERT (MonthDay, Title, VerseRef, VerseText, Body, Fixes, IsReviewed, UpdatedAt, UpdatedBy)
     VALUES (s.MonthDay, s.Title, s.VerseRef, s.VerseText, s.Body, s.Fixes, 1, DATEADD(HOUR, 9, SYSUTCDATETIME()), N'Claude');

COMMIT;

SELECT MonthDay, Title, VerseRef, IsReviewed, LEN(Body) AS BodyLen
FROM dbo.Prayer365 WHERE MonthDay IN ('0106', '0113', '1215') ORDER BY MonthDay;
